from pathlib import Path
names=['Atlas Studio','Signal Journey','Open Campus'];desc=['Dunkle Betriebswelt mit seitlicher Navigation, anklickbaren Themen und integriertem Lernstudio. Die ausgewogenste Mischung.','Filmische Bildbühne mit Themenkapiteln. Video, Werkzeug und Arbeitsunterlage bilden einen gemeinsamen Lernweg.','Heller Wissenscampus mit räumlichem Betriebsmodell und gezielt dunklen Medienbühnen. Offen, klar und hochwertig.']
css='''*{box-sizing:border-box}body{margin:0;background:#eaf1f8;color:#153352;font:16px/1.6 "Segoe UI",Arial,sans-serif}main{max-width:1480px;margin:auto;padding:50px 40px}h1{font-size:58px;line-height:1.04;letter-spacing:-.045em;max-width:1050px;margin:12px 0 25px}h2{font-size:30px;line-height:1.12;margin:12px 0}p{color:#536c86;max-width:880px}a{color:inherit}.eyebrow{font:11px Consolas,monospace;letter-spacing:.13em}nav{display:flex;gap:12px;flex-wrap:wrap;margin:25px 0 35px}nav a,.btn{display:inline-block;text-decoration:none;background:#fff;border:1px solid #a6bdda;border-radius:5px;padding:11px 17px;font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.card{background:#fff;border:1px solid #c2d2e5;border-radius:8px;overflow:hidden}.card img{display:block;width:100%}.copy{padding:25px}.copy p{font-size:14px}.links{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;margin-top:20px}.board{width:1700px;margin:0;padding:35px}.board h1{font-size:48px}.board .hero{display:grid;grid-template-columns:1280px 300px;gap:28px}.board figure{margin:0;background:#fff;border:1px solid #bacde2}.board figure img{width:100%;display:block}.board figcaption{font-size:16px;font-weight:600;padding:10px 17px}.board .sub{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin-top:28px}.overview{width:1800px;padding:40px}.overview h1{font-size:53px}.overview .copy{padding:24px}.overview h2{font-size:32px}.overview p{font-size:17px}.overview .grid{gap:24px}@media(max-width:850px){main{padding:30px 19px}.grid{grid-template-columns:1fr}h1{font-size:42px}}'''
Path('gallery.css').write_text(css,encoding='utf-8')
def shell(title,b,cl=''):return f'<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="gallery.css"><body class="{cl}">{b}</body></html>'
cards=[]
for n,name in enumerate(names,1):
 links=''.join(f'<a href="variante-{n}.html?page={p}&lang=de">{l}</a>' for p,l in [('home','Start'),('library','Bibliothek'),('product','Produkt'),('tools','Tools'),('studio','Studio')])
 cards.append(f'<article class="card"><a href="variante-{n}.html?lang=de"><img src="screenshots/0{n}-home.jpg" alt="{name} Website"></a><div class="copy"><div class="eyebrow">VARIANTE 0{n}</div><h2>{name}</h2><p>{desc[n-1]}</p><a class="btn" href="variante-{n}.html?lang=de">Website ausprobieren ↗</a><div class="links">{links}<a href="vorlage-0{n}.jpg">Bildvorlage</a><a href="screenshots/0{n}-home-full.jpg">Ganze Startseite</a></div></div></article>')
 title=f'<div class="eyebrow">SCUTORIA / BUSINESS ATLAS × SIGNAL STUDIO / 0{n}</div><h1>{name}</h1><p>{desc[n-1]}</p>'
 hero=f'<div class="hero"><figure><img src="screenshots/0{n}-home.jpg"><figcaption>Startseite / Desktop</figcaption></figure><figure><img src="screenshots/0{n}-home-mobile.jpg"><figcaption>Startseite / Mobil</figcaption></figure></div>'
 subs=''.join(f'<figure><img src="screenshots/0{n}-{p}.jpg"><figcaption>{l}</figcaption></figure>' for p,l in [('library','Bibliothek / Themen und Suche'),('product','Produktdetail / digitale Arbeitsunterlage'),('tools','Tools / verständlicher Arbeitsbereich'),('studio','Studio / Themenwege und Medien')])
 Path(f'board-{n}.html').write_text(shell(name,title+hero+'<div class="sub">'+subs+'</div><p>Designprototyp · zusätzliche Titel und Videoformate sind Konzepte · Bewegung in der interaktiven HTML-Vorlage.</p>','board'),encoding='utf-8')
Path('index.html').write_text(shell('Scutoria · Drei Atlas-Studio-Varianten','<main><div class="eyebrow">SCUTORIA / BUSINESS ATLAS × SIGNAL STUDIO</div><h1>Drei Wege vom Entdecken<br>zum Verstehen und Anwenden.</h1><p>Drei neu gestaltete Websitevarianten. Jede mit Startseite, Bibliothek, Produktdetail, Tools und Studio. Desktop und Mobil. Deutsch und Englisch. Themenpunkte, Suche, Tooldemo und startbare Storyboards lassen sich ausprobieren.</p><nav><a href="CLAUDE-UMSETZUNGSBRIEF.md">Präziser Umsetzungsbrief für Claude</a><a href="SCUTORIA-ATLAS-STUDIO.zip">Komplettpaket</a><a href="vergleich.jpg">Bildvergleich</a></nav><div class="grid">'+''.join(cards)+'</div><p>Empfehlung: Atlas Studio für die ausgewogenste Mischung. Signal Journey für stärkere Medienwirkung. Open Campus für einen hellen Fachverlag mit markanten Studioflächen. Keine Liveänderung erfolgt.</p></main>'),encoding='utf-8')
mini=''.join(f'<article class="card"><img src="screenshots/0{n}-home.jpg"><div class="copy"><div class="eyebrow">VARIANTE 0{n}</div><h2>{names[n-1]}</h2><p>{desc[n-1]}</p><img src="screenshots/0{n}-studio.jpg" alt="Studio Unterseite"><p>Startseite oben · Studio unten<br>Weitere Vorlagen: Bibliothek, Produkt, Tools und Mobil.</p></div></article>' for n in range(1,4))
Path('overview.html').write_text(shell('Drei neue Scutoria-Varianten','<div class="eyebrow">SCUTORIA / BUSINESS ATLAS × SIGNAL STUDIO</div><h1>Drei neue Websitevarianten.</h1><p>Eine erkundbare Betriebswelt. Ein filmisches Lernstudio. Ein klarer Weg zur Anwendung.</p><div class="grid">'+mini+'</div>','overview'),encoding='utf-8')
